FROM sys_ai_service_access_log l
INNER JOIN sys_ai_app_key k
        ON k.sys_ai_app_key_app_key = l.app_key
       AND k.sys_ai_app_key_delete = 0
WHERE l.create_time >= #{since}
  AND l.router_group = #{routerGroup}



            AND k.sys_ai_app_key_user_id = #{ownerUserId}


            AND k.sys_ai_app_key_user_id IS NULL
